#[derive(Debug, Clone)]
pub struct ActionError {
    pub code: &'static str,
    pub message: String,
}

impl ActionError {
    pub(crate) fn new(code: &'static str, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }
}

impl std::fmt::Display for ActionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for ActionError {}

impl From<chromiumoxide::error::CdpError> for ActionError {
    fn from(err: chromiumoxide::error::CdpError) -> Self {
        ActionError::new("cdp_error", err.to_string())
    }
}

fn is_detached_error(err: &chromiumoxide::error::CdpError) -> bool {
    let msg = err.to_string().to_lowercase();
    msg.contains("node")
        && (msg.contains("not found")
            || msg.contains("no node")
            || msg.contains("could not find node")
            || msg.contains("backend node")
            || msg.contains("detached"))
}

fn map_cdp_error(err: chromiumoxide::error::CdpError, context: &'static str) -> ActionError {
    if is_detached_error(&err) {
        ActionError::new(
            "stale_element",
            format!("element detached or stale during {context}"),
        )
    } else {
        ActionError::new("cdp_error", err.to_string())
    }
}

impl ActionApplier {
    pub fn new(max_scroll: i64) -> Self {
        Self { max_scroll }
    }

    pub async fn apply(
        &self,
        page: &Page,
        action: &Action,
        element_map: Option<&HashMap<String, BackendNodeId>>,
    ) -> Result<ApplyOutcome, ActionError> {
        let outcome = match action {
            Action::Click { id } => {
                click_by_id(page, id, element_map).await?;
                ApplyOutcome::none()
            }
            Action::Type { id, text, submit } => {
                type_by_id(page, id, text, submit.unwrap_or(false), element_map).await?;
                ApplyOutcome::none()
            }
            Action::Select { id, value } => {
                select_by_id(page, id, value, element_map).await?;
                ApplyOutcome::none()
            }
            Action::Scroll { dx, dy } => {
                let scroll = scroll_by(page, *dx, *dy, self.max_scroll).await?;
                ApplyOutcome {
                    extract: None,
                    scroll: Some(scroll),
                }
            }
            Action::Wait { ms } => {
                sleep(Duration::from_millis(*ms)).await;
                ApplyOutcome::none()
            }
            Action::Navigate { url } => {
                page.goto(url.as_str()).await?;
                ApplyOutcome::none()
            }
            Action::Back => {
                page.evaluate("() => history.back()").await?;
                ApplyOutcome::none()
            }
            Action::Extract { query, id } => {
                let value = if let Some(target) = id.as_deref() {
                    extract_by_id(page, target, query, element_map).await?
                } else {
                    extract_from_page(page, query).await?
                };
                ApplyOutcome {
                    extract: Some(ExtractResult {
                        query: query.to_string(),
                        id: id.clone(),
                        value,
                    }),
                    scroll: None,
                }
            }
            Action::Done { .. } => ApplyOutcome::none(),
        };
        Ok(outcome)
    }
}

pub fn action_result_ok(extract: Option<ExtractResult>) -> StepResult {
    StepResult {
        ok: true,
        error: None,
        new_state_hash: None,
        extract,
        scroll: None,
    }
}

pub fn action_result_err(error: ActionError) -> StepResult {
    StepResult {
        ok: false,
        error: Some(StepError {
            code: error.code.to_string(),
            message: error.message,
        }),
        new_state_hash: None,
        extract: None,
        scroll: None,
    }
}

async fn scroll_by(
    page: &Page,
    dx: i64,
    dy: i64,
    max_scroll: i64,
) -> Result<[f64; 2], ActionError> {
    if dx.saturating_abs() > max_scroll || dy.saturating_abs() > max_scroll {
        return Err(ActionError::new(
            "scroll_out_of_bounds",
            format!("scroll out of bounds: dx={dx}, dy={dy}, max={max_scroll}"),
        ));
    }
    let script = format!("() => {{ window.scrollBy({dx}, {dy}); return [window.scrollX, window.scrollY]; }}");
    let result = page.evaluate(script).await?;
    let value = result
        .into_value()
        .map_err(|err| ActionError::new("js_error", format!("scroll: {err}")))?;
    let coords: [f64; 2] = serde_json::from_value(value)
        .map_err(|err| ActionError::new("js_error", format!("scroll: {err}")))?;
    Ok(coords)
}

